package com.wartec.wartecmod.port;
import com.wartec.wartecmod.port.planning.*;
import java.util.*;
import net.minecraft.nbt.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class AttackPlanBuilderTest {
    @Test public void differentCustomConfigurationsRemainSeparateChoices(){AttackOperation o=operation();NBTTagCompound a=asset("RELEASE");store(a,0,0,1,true);store(a,1,0,1,true);a.getTagList("Stores",10).getCompoundTagAt(0).setString("Signature","HE-build");a.getTagList("Stores",10).getCompoundTagAt(1).setString("Signature","cluster-build");assertEquals(2,AttackPlanBuilder.weapons(a,o).size());List<AttackOperation.Step> choice=AttackPlanBuilder.build(o,a,"wartecmod:rocket:0:cluster-build",1,700,64,0,0,20,false);assertEquals(1,choice.get(0).slot);}
    private AttackOperation operation(){AttackOperation o=new AttackOperation();o.scope="team:blue";o.author=UUID.randomUUID();return o;}
    private NBTTagCompound asset(String actions){NBTTagCompound a=new NBTTagCompound();a.setString("Key","unit");a.setString("Actions",actions);a.setBoolean("Attack",true);a.setTag("Stores",new NBTTagList());return a;}
    private void store(NBTTagCompound a,int slot,int meta,int count,boolean weapon){NBTTagCompound s=new NBTTagCompound();s.setString("Item","wartecmod:rocket");s.setInteger("Meta",meta);s.setInteger("Slot",slot);s.setInteger("Count",count);s.setBoolean("Launchable",weapon);a.getTagList("Stores",10).appendTag(s);}
    @Test public void mixedMlrsPayloadsReserveExactPhysicalTubes(){AttackOperation o=operation();NBTTagCompound a=asset("PREPARE,LAUNCH");store(a,0,0,1,true);store(a,1,1,1,true);store(a,2,0,1,true);store(a,3,0,1,false);List<NBTTagCompound> choices=AttackPlanBuilder.weapons(a,o);assertEquals(2,choices.size());assertEquals(2,choices.get(0).getInteger("Available"));List<AttackOperation.Step> steps=AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",2,500,64,400,200,40,false);assertEquals(3,steps.size());assertEquals(AttackOperation.Action.PREPARE,steps.get(0).action);assertEquals(200,steps.get(0).offset);assertEquals(0,steps.get(1).slot);assertEquals(2,steps.get(2).slot);assertEquals(1,steps.get(2).count);o.steps.addAll(steps);assertEquals("",o.validate());assertEquals(1,AttackPlanBuilder.weapons(a,o).size());assertEquals(1,AttackPlanBuilder.weapons(a,o).get(0).getInteger("Meta"));}
    @Test public void carrierGetsTakeoffReleaseAndReturnButAirborneSkipsTakeoff(){AttackOperation o=operation();NBTTagCompound a=asset("TAKEOFF,RELEASE,RETURN");store(a,2,0,2,true);List<AttackOperation.Step> steps=AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",2,700,64,50,60,30,true);assertEquals(4,steps.size());assertEquals(2,steps.get(0).slot);assertEquals(AttackOperation.Action.TAKEOFF,steps.get(0).action);assertEquals(AttackOperation.Action.RETURN,steps.get(3).action);assertEquals(steps.get(2).id,steps.get(3).after);a.setBoolean("Airborne",true);assertEquals(AttackOperation.Action.RELEASE,AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",1,700,64,50,60,30,true).get(0).action);}
    @Test public void oneWayHasSingleWarheadAndNoReturnOrNumericHardpoint(){AttackOperation o=operation();NBTTagCompound a=asset("TAKEOFF,RELEASE,RETURN");a.setBoolean("OneWay",true);a.setInteger("Ammo",1);List<AttackOperation.Step> steps=AttackPlanBuilder.build(o,a,"self",1,500,64,500,0,20,true);assertEquals(2,steps.size());assertEquals(-1,steps.get(1).slot);o.steps.addAll(steps);assertTrue(AttackPlanBuilder.weapons(a,o).isEmpty());}
    @Test public void oldAutomaticReservationsAlsoConsumeVisibleAvailableStores(){AttackOperation o=operation();NBTTagCompound a=asset("LAUNCH");store(a,0,0,3,true);AttackOperation.Step old=new AttackOperation.Step();old.asset="unit";old.count=2;o.steps.add(old);assertEquals(1,AttackPlanBuilder.weapons(a,o).get(0).getInteger("Available"));}
    @Test public void invalidQuantityDoesNotMutateDraft(){AttackOperation o=operation();NBTTagCompound a=asset("LAUNCH");store(a,0,0,1,true);try{AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",2,500,64,500,0,20,false);fail();}catch(IllegalArgumentException e){assertEquals("error.empty",e.getMessage());}assertTrue(o.steps.isEmpty());}
    @Test public void freshTelemetryPreventsStaleWeaponChoice(){AttackOperation o=operation();NBTTagCompound a=asset("LAUNCH");store(a,0,0,1,true);a.setTag("Stores",new NBTTagList());try{AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",1,500,64,500,0,20,false);fail();}catch(IllegalArgumentException e){assertEquals("error.empty",e.getMessage());}}
    @Test public void additionsWaitForPreviousAssignmentAndKeepPersistence(){AttackOperation o=operation();NBTTagCompound a=asset("PREPARE,LAUNCH");store(a,0,0,2,true);o.steps.addAll(AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",1,500,64,500,0,20,false));UUID parent=o.steps.get(1).id;List<AttackOperation.Step> more=AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",1,800,80,600,100,20,false);assertEquals(parent,more.get(0).after);o.steps.addAll(more);AttackOperation saved=AttackOperation.read(o.write());assertEquals("",saved.validate());assertEquals(100,saved.steps.get(2).offset);assertEquals(800,saved.steps.get(3).x);assertEquals(AttackOperation.Event.COMPLETE,saved.steps.get(3).event);}
    @Test public void unsafeCoordsTimingAndRunningPlanAreRejected(){NBTTagCompound a=asset("LAUNCH");store(a,0,0,1,true);AttackOperation o=operation();for(int badY:new int[]{-1,256})try{AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",1,0,badY,0,0,20,false);fail();}catch(IllegalArgumentException expected){}try{AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",1,0,64,0,-1,20,false);fail();}catch(IllegalArgumentException expected){}o.state=AttackOperation.State.RUNNING;try{AttackPlanBuilder.build(o,a,"wartecmod:rocket:0",1,0,64,0,0,20,false);fail();}catch(IllegalArgumentException e){assertEquals("draft_only",e.getMessage());}}
}
